/bin/zsh -lc "python3 -B -c 'import json
with open(\"input.json\") as f:
    x = json.load(f)
def covered(start, finish, intervals):
    cursor = start
    for a, b in sorted(intervals):
        if b <= cursor:
            continue
        if a > cursor:
            return False
        cursor = b
        if cursor >= finish:
            return True
    return False
starts = []
for start in range(x[\"window_start\"], x[\"window_end\"] - x[\"duration\"] + 1):
    finish = start + x[\"duration\"]
    if finish > x[\"deadline\"]:
        continue
    if not all(covered(start, finish, intervals) for intervals in x[\"teams\"].values()):
        continue
    if any(start < b and a < finish for a, b in x[\"blackouts\"]):
        continue
    starts.append(start)
print(json.dumps({\"feasible_starts\": starts, \"earliest\": starts[0] if starts else None, \"latest\": starts[-1] if starts else None}, separators=(\",\", \":\")))'"

